INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Datenschutzgesetze > EU-Ebene (DSGVO)
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die DSGVO (Datenschutz-Grundverordnung) für alle Unternehmen in der EU verpflichtend?', 2, '[{"text": "Ja", "correct": true, "because": "Sie gilt für alle, die personenbezogene Daten verarbeiten"}, {"text": "Nein", "correct": false, "because": "Ausnahmen sind minimal"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die DSGVO auch auf Unternehmen außerhalb der EU angewendet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Wenn sie Daten von EU-Bürgern verarbeiten, gilt die DSGVO"}, {"text": "Nein", "correct": false, "because": "Extraterritoriale Anwendung ist vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss jede Datenverarbeitung nach der DSGVO eine Einwilligung der Betroffenen erfordern?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Rechtsgrundlagen wie Vertragserfüllung sind möglich"}, {"text": "Ja", "correct": false, "because": "Einwilligung ist nur eine Option"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verstöße gegen die DSGVO mit Geldbußen geahndet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Bußgelder bis zu 20 Mio. Euro oder 4% des Jahresumsatzes"}, {"text": "Nein", "correct": false, "because": "Sanktionen sind vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die DSGVO ausschließlich auf digitale Daten beschränkt?', 2, '[{"text": "Nein", "correct": true, "because": "Sie gilt auch für papierbasierte Datenverarbeitung"}, {"text": "Ja", "correct": false, "because": "Umfasst alle personenbezogenen Daten"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die DSGVO primär?', 2, '[{"text": "Schutz personenbezogener Daten", "correct": true, "because": "Datenschutz und Privatsphäre sind zentral"}, {"text": "Förderung der Digitalisierung", "correct": false, "because": "Kein primäres Ziel"}, {"text": "Kostensenkung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht gewährt die DSGVO den Betroffenen am häufigsten?', 3, '[{"text": "Recht auf Auskunft", "correct": true, "because": "Betroffene können ihre Daten einsehen"}, {"text": "Recht auf Vergessenwerden", "correct": false, "because": "Wichtig, aber nicht primär"}, {"text": "Recht auf Datenportabilität", "correct": false, "because": "Spezifisches Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflicht ist für Unternehmen nach der DSGVO am wichtigsten?', 2, '[{"text": "Datenschutz durch Technik und Voreinstellung", "correct": true, "because": "Privacy by Design und Default sind zentral"}, {"text": "Jährliche Berichterstattung", "correct": false, "because": "Nicht vorgeschrieben"}, {"text": "Softwarezertifizierung", "correct": false, "because": "Kein direkter Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strafe droht bei schweren Verstößen gegen die DSGVO maximal?', 2, '[{"text": "20 Mio. Euro oder 4% des Jahresumsatzes", "correct": true, "because": "Höchstes Bußgeld nach DSGVO"}, {"text": "1 Mio. Euro", "correct": false, "because": "Zu niedrig"}, {"text": "Verwarnung", "correct": false, "because": "Nur bei leichten Verstößen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle überwacht die Einhaltung der DSGVO in Unternehmen?', 2, '[{"text": "Datenschutzbeauftragter", "correct": true, "because": "Pflicht bei umfangreicher Datenverarbeitung"}, {"text": "IT-Administrator", "correct": false, "because": "Technische Rolle"}, {"text": "Marketing-Manager", "correct": false, "because": "Kein Datenschutzfokus"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rechte gewährt die DSGVO den Betroffenen?', 4, '[{"text": "Recht auf Auskunft", "correct": true, "because": "Einblick in verarbeitete Daten"}, {"text": "Recht auf Löschung", "correct": true, "because": "Daten können entfernt werden"}, {"text": "Recht auf Datenportabilität", "correct": true, "because": "Datenübertragung möglich"}, {"text": "Recht auf kostenlose Software", "correct": false, "because": "Kein DSGVO-Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen nach der DSGVO?', 3, '[{"text": "Datenverarbeitung dokumentieren", "correct": true, "because": "Verzeichnis ist vorgeschrieben"}, {"text": "Datenschutz-Folgenabschätzung", "correct": true, "because": "Bei hohem Risiko nötig"}, {"text": "Einwilligung einholen", "correct": true, "because": "Wenn keine andere Grundlage"}, {"text": "Jährliche Softwaretests", "correct": false, "because": "Nicht vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien legt die DSGVO für die Datenverarbeitung fest?', 4, '[{"text": "Rechtmäßigkeit", "correct": true, "because": "Verarbeitung muss legal sein"}, {"text": "Transparenz", "correct": true, "because": "Klarheit für Betroffene"}, {"text": "Datenminimierung", "correct": true, "because": "Nur notwendige Daten"}, {"text": "Maximale Speicherung", "correct": false, "because": "Speicherbegrenzung vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen bei Verstößen gegen die DSGVO?', 3, '[{"text": "Geldbußen", "correct": true, "because": "Bis zu 20 Mio. Euro"}, {"text": "Verarbeitungsverbote", "correct": true, "because": "Kann verhängt werden"}, {"text": "Schadensersatzansprüche", "correct": true, "because": "Betroffene können klagen"}, {"text": "Pflicht zur Softwareentwicklung", "correct": false, "because": "Keine Sanktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Daten fallen unter den Schutz der DSGVO?', 3, '[{"text": "Personenbezogene Daten", "correct": true, "because": "Kern der Verordnung"}, {"text": "Gesundheitsdaten", "correct": true, "because": "Besonders geschützt"}, {"text": "Anonymisierte Daten", "correct": false, "because": "Nicht personenbezogen"}, {"text": "Finanzdaten", "correct": true, "because": "Wenn personenbezogen"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die DSGVO schützt personenbezogene Daten. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, auch papierbasierte Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Unternehmen außerhalb der EU können unter die DSGVO fallen. b) Eine Einwilligung ist immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Extraterritorial ja, Einwilligung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verstöße gegen die DSGVO können mit Bußgeldern geahndet werden. b) Sie gilt nur für große Unternehmen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, alle Unternehmen betroffen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die DSGVO fordert Datenschutz durch Technikgestaltung. b) Ein Datenschutzbeauftragter ist immer optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technikgestaltung ja, Beauftragter oft Pflicht"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Das Recht auf Auskunft ist ein Betroffenenrecht nach DSGVO. b) Die DSGVO schützt nur EU-Bürger innerhalb der EU.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auskunft ja, Schutz auch außerhalb"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

